package __PKG__;

import com.mojang.brigadier.arguments.StringArgumentType;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.minecraft.commands.CommandSourceStack;
import net.minecraft.commands.Commands;
import net.minecraft.server.level.ServerPlayer;

/**
 * The custom items of the resource pack and the command that hands them out:
 * /__CMD__ <item> [amount] [player]. Generated by Minecraft Builder.
 */
public final class CustomItems {
    /** key, base item, model, name, lore */
    static final String[][] ITEMS = {
__ITEMS__
    };

    private CustomItems() {}

    static void init() {
        String[] keys = new String[ITEMS.length];
        for (int i = 0; i < ITEMS.length; i++) keys[i] = ITEMS[i][0];
        final String[][] tab = { keys, { "1", "16", "64" }, { "@players" } };
        CommandRegistrationCallback.EVENT.register((dispatcher, registryAccess, environment) -> {
            dispatcher.register(Commands.literal("__CMD__")
                .requires(Util::isOp)
                .executes(ctx -> run(ctx.getSource(), new String[0]))
                .then(Commands.argument("args", StringArgumentType.greedyString())
                    .suggests((ctx, builder) -> Util.suggestArgs(builder, tab))
                    .executes(ctx -> run(ctx.getSource(), StringArgumentType.getString(ctx, "args").trim().split("\\s+")))));
        });
    }

    private static int run(final CommandSourceStack source, final String[] args) {
        if (args.length == 0) {
            StringBuilder sb = new StringBuilder("&7Items: &f");
            for (int i = 0; i < ITEMS.length; i++) sb.append(i > 0 ? "&7, &f" : "").append(ITEMS[i][0]);
            source.sendSystemMessage(Util.color(sb.toString()));
            return 1;
        }
        String[] item = null;
        for (String[] it : ITEMS) {
            if (it[0].equalsIgnoreCase(args[0])) item = it;
        }
        if (item == null) {
            source.sendSystemMessage(Util.color("&cUnknown item: " + args[0]));
            return 0;
        }
        double amount = args.length > 1 ? Math.max(1, Util.num(args[1])) : 1;
        ServerPlayer target = args.length > 2 ? Util.findPlayer(args[2]) : source.getPlayer();
        if (target == null) {
            source.sendSystemMessage(Util.color("&cPlayer not found."));
            return 0;
        }
        Util.giveCustom(target, item[1], amount, item[2], item[3], item[4]);
        source.sendSystemMessage(Util.color("&a" + Util.name(target) + " &7+ &f" + (int) amount + "x " + item[0]));
        return 1;
    }
}
